#!/usr/bin/env python3
# SPDX-License-Identifier: GPL-3.0-only
# SKYLYNNE: the tables of firmware/src/sky.c (the resonators): SKY_W[note] = the pole angle of MIDI note n at 44.1 kHz
# in Q29 radians, SKY_R[i] = the pole radius for a ring-out time constant of 0.03 s * 1.28^i, in Q29.
#   python3 tools/gen_sky_tables.py > firmware/src/sky_tables.h
import math
FS = 44100.0
out = ["/* SPDX-License-Identifier: GPL-3.0-only */",
       "/* generated by tools/gen_sky_tables.py: do not edit */",
       "static const uint32_t SKY_W[128] = {"]
row = []
for n in range(128):
    f = 440.0 * 2 ** ((n - 69) / 12.0)
    w = 2 * math.pi * f / FS
    row.append(str(min(int(round(w * 2 ** 29)), 0xFFFFFFFF)) + "u")
for i in range(0, 128, 8):
    out.append("    " + ", ".join(row[i:i + 8]) + ",")
out.append("};")
out.append("static const int32_t SKY_R[24] = {")
rr = []
for i in range(24):
    tau = 0.03 * 1.28 ** i
    r = math.exp(-1.0 / (tau * FS))
    rr.append(str(int(round(r * 2 ** 29))))
for i in range(0, 24, 6):
    out.append("    " + ", ".join(rr[i:i + 6]) + ",")
out.append("};")
out.append("static const uint32_t SKY_TAU[24] = {   /* samples of one time constant */")
tt = [str(int(round(0.03 * 1.28 ** i * FS))) + "u" for i in range(24)]
for i in range(0, 24, 6):
    out.append("    " + ", ".join(tt[i:i + 6]) + ",")
out.append("};")
print("\n".join(out))
